import original, tempfile, pathlib, json
with tempfile.TemporaryDirectory(dir='.') as directory:
    q = original.Queue(pathlib.Path(directory) / 'queue.db')
    q.put('one', {})
    for duration in (True,):
        try:
            print('duration', repr(duration), 'returned', q.claim('worker', 0, duration))
        except Exception as exc:
            print(type(exc).__name__)
    try:
        q.put('\\ud800', 'payload')
    except Exception as exc:
        print('surrogate ID:', type(exc).__name__)
    try:
        print(q.claim('\\ud800', 1, 1))
    except Exception as exc:
        print('surrogate worker:', type(exc).__name__)
    for depth in range(970, 1005):
        p = None
        for _ in range(depth):
            p = [p]
        try:
            q.put(str(depth), p)
        except (TypeError, ValueError, RecursionError):
            continue
        try:
            result = q.claim('worker', depth, 1)
            q.ack(result['receipt'], depth)
        except RecursionError:
            print('accepted payload cannot be delivered at depth:', depth)
            break
PY"

